package app.zhijian.notes;
import org.json.*;import org.junit.Test;import static org.junit.Assert.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.Files;import java.util.*;import java.util.zip.*;
import app.zhijian.notes.backup.*;
public class ArchiveExtrasTest{
 private static final String A="11111111-1111-1111-1111-111111111111",B="22222222-2222-2222-2222-222222222222";
 private JSONObject file()throws Exception{return new JSONObject().put("src","media/a.bin").put("name","阅读资料.pdf").put("mime","application/pdf").put("size",4);}
 private JSONObject note(String id,String content)throws Exception{return new JSONObject().put("id",id).put("title",id).put("mode","markdown").put("content",content).put("tags",new JSONArray()).put("folderId",JSONObject.NULL);}
 private JSONObject snapshot(JSONArray notes)throws Exception{return new JSONObject().put("format","paper-notes").put("version",1).put("notes",notes).put("folders",new JSONArray()).put("todos",new JSONArray()).put("media",new JSONObject());}
 @Test public void reimportDoesNotDuplicateNewNoteWhoseTargetWasRemapped()throws Exception{JSONObject local=snapshot(new JSONArray().put(note(B,"本机B"))),incoming=snapshot(new JSONArray().put(note(A,"[相关](paper-note:"+B+")")).put(note(B,"备份B")));JSONObject once=MergePlanner.plan(local,incoming),twice=MergePlanner.plan(once,incoming);assertEquals(3,once.getJSONArray("notes").length());assertEquals(3,twice.getJSONArray("notes").length());}
 @Test public void historyPicturesAndFilesRemainReferenced()throws Exception{JSONObject n=note(A,"![](media/new.png)").put("attachments",new JSONArray().put(file())).put("_history",new JSONArray().put(note(A,"![](media/old.png)").put("attachments",new JSONArray().put(file().put("src","media/old.bin")))));assertEquals(new HashSet<>(Arrays.asList("new.png","old.png","a.bin","old.bin")),ArchiveCodec.noteReferences(n));}
 @Test public void conflictsRemapHistoricalMediaFilesAndImportedLinks()throws Exception{JSONObject local=snapshot(new JSONArray().put(note(A,"本机 A")).put(note(B,"本机 B")));local.getJSONObject("media").put("a.bin","local").put("old.png","local");JSONObject incoming=snapshot(new JSONArray().put(note(A,"[相关](paper-note:"+B+")").put("attachments",new JSONArray().put(file())).put("_history",new JSONArray().put(note(A,"![](media/old.png)")))).put(note(B,"备份 B")));incoming.getJSONObject("media").put("a.bin","backup").put("old.png","backup");JSONObject merged=MergePlanner.plan(local,incoming),imported=merged.getJSONArray("notes").getJSONObject(2),target=merged.getJSONArray("notes").getJSONObject(3);assertTrue(imported.getString("content").contains("paper-note:"+target.getString("id")));assertNotEquals("media/a.bin",imported.getJSONArray("attachments").getJSONObject(0).getString("src"));assertFalse(imported.getJSONArray("_history").getJSONObject(0).getString("content").contains("media/old.png"));assertEquals(4,MergePlanner.plan(merged,incoming).getJSONArray("notes").length());}
 @Test public void markdownExportIncludesNamedAttachmentsAndRelativeNoteLinks()throws Exception{File dir=Files.createTempDirectory("paper-export-test").toFile();File attachment=new File(dir,"a.bin");try{Files.write(attachment.toPath(),new byte[]{1,2,3,4});JSONObject n=new JSONObject().put("id",A).put("title","资料").put("markdown","[相关](paper-note:"+B+")").put("attachments",new JSONArray().put(file()));ByteArrayOutputStream bytes=new ByteArrayOutputStream();ArchiveCodec.writeMarkdown(bytes,new JSONArray().put(n).put(new JSONObject().put("id",B).put("title","相关").put("markdown","正文")),dir);Map<String,byte[]> entries=new HashMap<>();try(ZipInputStream zip=new ZipInputStream(new ByteArrayInputStream(bytes.toByteArray()))){ZipEntry entry;while((entry=zip.getNextEntry())!=null)entries.put(entry.getName(),zip.readAllBytes());}String markdown=new String(entries.get(A+".md"),StandardCharsets.UTF_8);assertTrue(markdown,markdown.contains(B+".md"));String exported=entries.keySet().stream().filter(name->name.endsWith("阅读资料.pdf")).findFirst().orElse("");assertFalse(exported.isEmpty());assertTrue(markdown.contains(exported));assertArrayEquals(new byte[]{1,2,3,4},entries.get(exported));}finally{attachment.delete();dir.delete();}}
}
